use crate::{firewall, network, upnp};
use anyhow::Context;
use serde_json::{json, Value};
use std::{net::Ipv4Addr, thread};
use winit::{application::ApplicationHandler,event::WindowEvent,event_loop::{ActiveEventLoop,EventLoopProxy},window::{Window,WindowId}};
use wry::{WebView,WebViewBuilder};

const HTML:&str=r##"<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MalachiteVR Network Manager</title><style>:root{font-family:Segoe UI,system-ui,sans-serif;color:#e9f4ed;background:#0b100e;--g:#4cbe73;--g2:#79d99a;--line:#24372b;--muted:#91a59a;--danger:#e56b6f}*{box-sizing:border-box}body{margin:0;height:100vh;overflow:hidden;background:radial-gradient(circle at 80% -10%,#193c27 0,#0b100e 42%)}#app{display:flex;width:100%;height:100%}.side{width:240px;background:#090e0b;border-right:1px solid var(--line);padding:24px 15px;display:flex;flex-direction:column}.brand{padding:8px 12px 25px}.brand b{display:block;color:var(--g2);font-size:22px;letter-spacing:1.5px}.brand span{color:#718178;font-size:11px;letter-spacing:2px}.nav{display:grid;gap:7px}.nav button{border:1px solid transparent;background:transparent;color:#9cad9f;text-align:left;padding:13px 14px;border-radius:10px;font-size:14px;cursor:pointer}.nav button.active,.nav button:hover{background:#142019;color:#fff}.nav button.active{border-color:#28543a;box-shadow:inset 3px 0 0 var(--g)}.sidefoot{margin-top:auto;color:#617168;font-size:11px;padding:10px 12px}.main{flex:1;min-width:0;overflow:auto;padding:34px 40px}.top{display:flex;align-items:flex-start;justify-content:space-between;gap:20px;margin-bottom:25px}.eyebrow{color:var(--g);font-size:11px;letter-spacing:2px;font-weight:700}.title{font-size:30px;font-weight:750;margin:5px 0}.sub,p{color:var(--muted);font-size:14px}.btn{border:1px solid #31543f;background:#17271d;color:#dce9df;border-radius:9px;padding:10px 14px;cursor:pointer;font-weight:600}.btn:hover{background:#1d3426}.btn.primary{background:var(--g);border-color:var(--g);color:#07110a}.btn.danger{color:#ffb7b9;border-color:#633337;background:#261416}.cards{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}.card,.panel{background:#0f1813e6;border:1px solid var(--line);border-radius:15px;padding:18px}.panel{margin-top:16px}.label{font-size:11px;color:#718178;letter-spacing:1.5px}.value{font-size:28px;font-weight:750;margin-top:7px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.field{display:grid;gap:7px}.field label{font-size:12px;color:#84968c}.input,select{width:100%;background:#0d1510;border:1px solid #2a3c31;border-radius:8px;color:#e8f1ea;padding:10px;outline:none}.tablewrap{overflow:auto;border:1px solid var(--line);border-radius:11px;margin-top:15px}.table{width:100%;border-collapse:collapse;font-size:13px}.table th,.table td{padding:11px 12px;border-bottom:1px solid #1d2a22;white-space:nowrap}.table th{color:#718178;text-align:left;font-size:11px;text-transform:uppercase;letter-spacing:1px;background:#101912}.pill{display:inline-flex;padding:4px 8px;border-radius:99px;background:#183321;color:#82dca1;font-size:11px;font-weight:700}.pill.off{background:#252b27;color:#849087}.gateway{padding:13px;border:1px solid var(--line);border-radius:10px;margin-top:8px;cursor:pointer}.gateway.selected{border-color:#3e7955;background:#14241a}.small{font-size:11px;color:#65766c;word-break:break-all}.empty{text-align:center;padding:35px;color:#718178}.mono{font-family:Consolas,monospace;white-space:pre;line-height:1.55;color:#b9c9bf;font-size:12px}.section{display:none}.section.active{display:block}.status{position:fixed;right:24px;bottom:20px;background:#17251c;border:1px solid #31543f;border-radius:10px;padding:10px 14px;color:#c9d8ce;font-size:12px;opacity:0;transition:.2s}.status.show{opacity:1}@media(max-width:900px){.side{width:200px}.main{padding:25px}.cards{grid-template-columns:repeat(2,1fr)}}</style></head><body><div id="app"><aside class="side"><div class="brand"><b>MALACHITEVR</b><span>NETWORK MANAGER</span></div><div class="nav"><button data-page="overview" class="active">◈ &nbsp; Overview</button><button data-page="adapters">▦ &nbsp; Network Adapters</button><button data-page="connections">⇄ &nbsp; Connections</button><button data-page="firewall">◉ &nbsp; Windows Firewall</button><button data-page="upnp">↗ &nbsp; UPnP / Forwarding</button></div><div class="sidefoot">MalachiteeVR<br>Windows · WebView2</div></aside><main class="main"><section id="overview" class="section active"><div class="top"><div><div class="eyebrow">SYSTEM STATUS</div><div class="title">Network overview</div><div class="sub">A quiet control center for your Windows networking stack.</div></div><button class="btn" onclick="send('refresh')">Refresh</button></div><div class="cards"><div class="card"><div class="label">ADAPTERS</div><div class="value" id="cAdapters">0</div></div><div class="card"><div class="label">ACTIVE</div><div class="value" id="cActive">0</div></div><div class="card"><div class="label">FIREWALL</div><div class="value" id="cRules">0</div></div><div class="card"><div class="label">UPnP</div><div class="value" id="cUpnp">0</div></div></div><div class="panel"><h3>Private network</h3><p>Your detected LAN address used for new port mappings.</p><div id="ip" class="value" style="font-size:21px">Detecting…</div></div></section><section id="adapters" class="section"><div class="top"><div><div class="eyebrow">NETWORK</div><div class="title">Network adapters</div><div class="sub">Interfaces reported directly by the Windows IP Helper API.</div></div><button class="btn" onclick="send('refresh')">Refresh</button></div><div class="tablewrap"><table class="table"><thead><tr><th>Name</th><th>Description</th><th>Status</th><th>Speed</th><th>MAC</th><th></th></tr></thead><tbody id="adapterRows"></tbody></table></div></section><section id="connections" class="section"><div class="top"><div><div class="eyebrow">SOCKETS</div><div class="title">Current TCP connections</div></div><button class="btn" onclick="send('connections')">Refresh</button></div><div class="panel"><div id="connectionsText" class="mono">Press Refresh to query Windows.</div></div></section><section id="firewall" class="section"><div class="top"><div><div class="eyebrow">SECURITY</div><div class="title">Windows Firewall</div></div></div><div class="panel"><div class="grid"><div class="field"><label>Rule name</label><input id="ruleName" class="input" value="Malachite Allow"></div><div class="field"><label>Port</label><input id="rulePort" class="input" value="25565"></div><div class="field"><label>Protocol</label><select id="ruleProto"><option>TCP</option><option>UDP</option></select></div></div><button class="btn primary" style="margin-top:15px" onclick="addFirewall()">Allow inbound</button></div><div class="tablewrap"><table class="table"><thead><tr><th>Rule</th><th>Direction</th><th>Action</th><th>Enabled</th><th>Protocol</th><th>Port</th><th>Profile</th><th></th></tr></thead><tbody id="firewallRows"></tbody></table></div></section><section id="upnp" class="section"><div class="top"><div><div class="eyebrow">NAT</div><div class="title">UPnP / port forwarding</div><div class="sub">Discover gateways, inspect existing mappings, and create new mappings.</div></div><button class="btn" onclick="send('discover')">Discover / Refresh</button></div><div id="gateways"></div><div class="panel"><h3>Existing UPnP rules</h3><div id="upnpRules" class="tablewrap"><div class="empty">Discover a gateway to load its port mappings.</div></div></div><div class="panel"><div class="grid"><div class="field"><label>External port</label><input id="ext" class="input" value="25565"></div><div class="field"><label>Internal port</label><input id="intp" class="input" value="25565"></div><div class="field"><label>Private IPv4</label><input id="client" class="input"></div><div class="field"><label>Description</label><input id="desc" class="input" value="MalachiteVR Network Manager"></div></div><div style="display:flex;gap:8px;margin-top:15px"><button class="btn primary" onclick="addUpnp('TCP')">Add TCP mapping</button><button class="btn" onclick="addUpnp('UDP')">Add UDP mapping</button></div></div></section></main></div><div id="status" class="status"></div><script>let gateways=[],selectedGateway=0;const esc=s=>String(s??'').replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));function send(action,data={}){window.ipc?.postMessage(JSON.stringify({action,...data}));toast('Working…')}function toast(t){let e=document.getElementById('status');e.textContent=t;e.classList.add('show');clearTimeout(window._toast);window._toast=setTimeout(()=>e.classList.remove('show'),2800)}function renderAdapters(a){cAdapters.textContent=a.length;cActive.textContent=a.filter(x=>x.status==='Up').length;adapterRows.innerHTML=a.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.description)}</td><td><span class="pill ${x.status==='Up'?'':'off'}">${esc(x.status)}</span></td><td>${esc(x.speed)}</td><td>${esc(x.mac||'—')}</td><td><button class="btn" onclick="send('toggle',{name:${JSON.stringify(x.name)},enable:${x.status!=='Up'}})">${x.status==='Up'?'Disable':'Enable'}</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No adapters found.</td></tr>'}function renderFirewall(r){cRules.textContent=r.length;firewallRows.innerHTML=r.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.direction)}</td><td>${esc(x.action)}</td><td>${esc(x.enabled)}</td><td>${esc(x.protocol)}</td><td>${esc(x.local_port)}</td><td>${esc(x.profile)}</td><td><button class="btn danger" onclick="send('firewall_remove',{name:${JSON.stringify(x.name)}})">Delete</button></td></tr>`).join('')||'<tr><td colspan="8" class="empty">No firewall rules returned.</td></tr>'}function renderRules(r,error){if(error){upnpRules.innerHTML=`<div class="empty">${esc(error)}</div>`;return}upnpRules.innerHTML=r.length?`<table class="table"><thead><tr><th>External</th><th>Protocol</th><th>Internal</th><th>Client</th><th>Enabled</th><th>Description</th><th>Lease</th></tr></thead><tbody>${r.map(x=>`<tr><td>${x.external_port}</td><td>${esc(x.protocol)}</td><td>${x.internal_port}</td><td>${esc(x.internal_client)}</td><td>${x.enabled?'Yes':'No'}</td><td>${esc(x.description||'—')}</td><td>${x.lease_duration?x.lease_duration+'s':'Permanent'}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">No UPnP port mappings are configured.</div>'}function renderGateways(g){gateways=g;cUpnp.textContent=g.length;if(selectedGateway>=g.length)selectedGateway=0;gatewaysEl.innerHTML=g.map((x,i)=>`<div class="gateway ${i===selectedGateway?'selected':''}" onclick="selectedGateway=${i};renderGateways(gateways)"><b>Gateway ${i+1}</b><div class="small">${esc(x.server||'Unknown device')}</div><div class="small">${esc(x.location)}</div></div>`).join('')||'<div class="panel empty">No UPnP gateways discovered.</div>';if(g.length)renderRules(g[selectedGateway].rules,g[selectedGateway].rules_error)}const gatewaysEl=document.getElementById('gateways');window.__nm_result=function(v){if(v.error){toast(v.error);return}if(v.message)toast(v.message);if(v.kind==='refresh'){renderAdapters(v.adapters||[]);renderFirewall(v.rules||[]);ip.textContent=v.ip||'Not detected';client.value=v.ip||'';if(v.warnings?.length)toast(v.warnings.join(' | '))}if(v.kind==='discover')renderGateways(v.devices||[]);if(v.kind==='connections')connectionsText.textContent=v.text||'No connections returned.'};function addFirewall(){let port=Number(rulePort.value);if(!port||port>65535)return toast('Port must be 1-65535');send('firewall_add',{name:ruleName.value,port,protocol:ruleProto.value})}function addUpnp(protocol){let external=Number(ext.value),internal=Number(intp.value);if(!gateways.length)return toast('Discover a gateway first');if(!external||!internal||external>65535||internal>65535)return toast('Ports must be 1-65535');send('upnp_add',{index:selectedGateway,external,internal,protocol,client:client.value,description:desc.value})}document.querySelectorAll('.nav button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.nav button').forEach(x=>x.classList.remove('active'));document.querySelectorAll('.section').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.getElementById(b.dataset.page).classList.add('active')});send('refresh');</script></body></html>"##;

enum UserEvent{Result(String)}
pub struct App{window:Option<Window>,webview:Option<WebView>,proxy:EventLoopProxy<UserEvent>}
impl App{pub fn new(proxy:EventLoopProxy<UserEvent>)->Self{Self{window:None,webview:None,proxy}}}

fn run_command(message:&str,proxy:&EventLoopProxy<UserEvent>){
    let parsed:Value=match serde_json::from_str(message){
        Ok(v)=>v,
        Err(e)=>{let _=proxy.send_event(UserEvent::Result(json!({"error":e.to_string()}).to_string()));return}
    };
    let action=match parsed.get("action").and_then(Value::as_str){
        Some(a)=>a.to_owned(),
        None=>{let _=proxy.send_event(UserEvent::Result(json!({"error":"Missing action"}).to_string()));return}
    };
    let proxy=proxy.clone();
    thread::spawn(move||{
        let result:anyhow::Result<Value>=(||{
            match action.as_str(){
                "refresh"=>{
                    let(adapters,ae)=match network::adapters(){Ok(v)=>(v,None),Err(e)=>(Vec::<network::Adapter>::new(),Some(format!("Adapters: {e}")))};
                    let(rules,fe)=match firewall::rules(){Ok(v)=>(v,None),Err(e)=>(Vec::<firewall::Rule>::new(),Some(format!("Firewall: {e}")))};
                    let(ip,ie)=match network::private_ipv4(){Ok(v)=>(v.map(|x|x.to_string()),None),Err(e)=>(None,Some(format!("LAN address: {e}")))};
                    let warnings:Vec<String>=[ae,fe,ie].into_iter().flatten().collect();
                    Ok(json!({"kind":"refresh","adapters":adapters,"rules":rules,"ip":ip,"warnings":warnings}))
                }
                "connections"=>Ok(json!({"kind":"connections","text":network::connections()?})),
                "discover"=>Ok(json!({"kind":"discover","devices":upnp::discover()?})),
                "toggle"=>{
                    let name=parsed.get("name").and_then(Value::as_str).context("Missing adapter name")?.to_owned();
                    let enable=parsed.get("enable").and_then(Value::as_bool).context("Missing enable state")?;
                    network::toggle(&name,enable)?;
                    Ok(json!({"message":format!("Adapter {}.",if enable{"enabled"}else{"disabled"})}))
                }
                "firewall_add"=>{
                    let name=parsed.get("name").and_then(Value::as_str).context("Missing rule name")?;
                    let port=parsed.get("port").and_then(Value::as_u64).context("Missing port")?;
                    let protocol=parsed.get("protocol").and_then(Value::as_str).context("Missing protocol")?;
                    if name.trim().is_empty()||!(1..=65535).contains(&port){anyhow::bail!("Rule name and a valid port are required")}
                    firewall::add(name,port as u16,protocol)?;
                    Ok(json!({"message":"Firewall rule added."}))
                }
                "firewall_remove"=>{
                    let name=parsed.get("name").and_then(Value::as_str).context("Missing rule name")?;
                    firewall::remove(name)?;
                    Ok(json!({"message":"Firewall rule removed."}))
                }
                "upnp_add"=>{
                    let index=parsed.get("index").and_then(Value::as_u64).context("Missing gateway index")? as usize;
                    let external=parsed.get("external").and_then(Value::as_u64).context("Missing external port")?;
                    let internal=parsed.get("internal").and_then(Value::as_u64).context("Missing internal port")?;
                    let protocol=parsed.get("protocol").and_then(Value::as_str).context("Missing protocol")?;
                    let client=parsed.get("client").and_then(Value::as_str).context("Missing private IPv4")?;
                    let description=parsed.get("description").and_then(Value::as_str).unwrap_or("MalachiteVR Network Manager");
                    if !(1..=65535).contains(&external)||!(1..=65535).contains(&internal){anyhow::bail!("Ports must be 1-65535")}
                    if !matches!(protocol,"TCP"|"UDP"){anyhow::bail!("Protocol must be TCP or UDP")}
                    let ip:Ipv4Addr=client.parse().context("Invalid private IPv4 address")?;
                    if !ip.is_private(){anyhow::bail!("The target address must be a private IPv4 address")}
                    let devices=upnp::discover()?;
                    let device=devices.get(index).context("Selected gateway no longer exists")?;
                    upnp::add(device,external as u16,internal as u16,protocol,client,description)?;
                    Ok(json!({"kind":"discover","devices":upnp::discover()?}))
                }
                _=>anyhow::bail!("Unknown command: {action}")
            }
        })();
        let payload=match result{Ok(v)=>v.to_string(),Err(e)=>json!({"error":e.to_string()}).to_string()};
        let _=proxy.send_event(UserEvent::Result(payload));
    });
}

impl ApplicationHandler<UserEvent> for App{fn resumed(&mut self,event_loop:&ActiveEventLoop){if self.window.is_some(){return}let attrs=Window::default_attributes().with_title("MalachiteVR Network Manager").with_inner_size(winit::dpi::LogicalSize::new(1280.0,820.0));let window=event_loop.create_window(attrs).expect("Failed to create window");let webview=WebViewBuilder::new().with_html(HTML).with_ipc_handler({let proxy=self.proxy.clone();move|request|run_command(request.body(),&proxy)}).build(&window).expect("Failed to initialize Microsoft Edge WebView2");self.webview=Some(webview);self.window=Some(window)}fn user_event(&mut self,_:&ActiveEventLoop,event:UserEvent){let UserEvent::Result(payload)=event;if let Some(webview)=&self.webview{let _=webview.evaluate_script(&format!("window.__nm_result({payload});"));}}fn window_event(&mut self,event_loop:&ActiveEventLoop,_:WindowId,event:WindowEvent){if matches!(event,WindowEvent::CloseRequested){event_loop.exit()}}}
pub fn run()->anyhow::Result<()>{let event_loop=winit::event_loop::EventLoop::<UserEvent>::with_user_event().build()?;let proxy=event_loop.create_proxy();let mut app=App::new(proxy);event_loop.run_app(&mut app)?;Ok(())}
